interface IVGHST is IERC20 {
    function enter(
        uint256 _amount
    ) external returns (uint256);
    function leave(
        uint256 _amount
    ) external;
    function convertVGHST(
        uint256 _share
    ) external view returns (uint256 _ghst);
}

interface IDMMLP {
    function swap(uint256 amount0Out, uint256 amount1Out, address to, bytes calldata callbackData) external;
}

interface IAlgebraPool {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function swap(
        address recipient,
        bool zeroToOne,
        int256 amountSpecified,
        uint160 limitSqrtPrice,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}

interface ISwapFlashLoan {
    function swap(
        uint8 tokenIndexFrom,
        uint8 tokenIndexTo,
        uint256 dx,
        uint256 minDy,
        uint256 deadline
    ) external returns (uint256);
